import {
  CAR_PROTECTION,
  EXTENDED_WARRANTY_PROTECTION,
  PROPERTY_PROTECTION,
  TRAVEL_PROTECTION,
} from '../../../../../constants/pkgCode'

export function getQsLink(policy) {
  switch (policy?.product_key) {
    case CAR_PROTECTION:
      return `https://${window.location.hostname}/motor_vehicle/draft/policy/${policy?.draft_id}/`
    case EXTENDED_WARRANTY_PROTECTION:
      return `https://${window.location.hostname}/extended_warranty/draft/policy/${policy?.draft_id}/`
    case TRAVEL_PROTECTION:
      return `https://${window.location.hostname}/travel/draft/policy/${policy?.draft_id}/`
    case PROPERTY_PROTECTION:
      return `https://${window.location.hostname}/property/draft/policy/${policy?.draft_id}/`
    default:
      return `https://${window.location.hostname}/customer/policy/${policy?.id}/`
  }
}
