import { useCallback, useEffect, useMemo } from 'react'
import { useHistory, useParams } from 'react-router-dom'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Container } from '../../../../../components'
// import { FLEET_POLICY, MANUAL_ORDER } from '../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../lang'
import customerActions from '../../../../../redux/customer/actions'
// import { useGetOfflineQuoteDetail } from '../../../../../state/commonState/hooks/useCommonContext'
import XenditPayment from '../../../../Private/Payments/pages/XenditPayment'
import { ButtonContainer, PaymentPageStyle, PolicySummary } from './index.style'
import { getQsLink } from './helpers'

const POLICY_SUMMARY = [
  { label: LANG_STRINGS.policyHolder1, key: 'customer_data.name' },
  { label: LANG_STRINGS.typeInsurance, key: 'product.package.product.name' },
  { label: LANG_STRINGS.agentName, key: 'agent_info.name' },
  { label: LANG_STRINGS.packageTitle, key: 'product.package.name' },
]

function CustomerPaymentContainer(props) {
  const { customerPolicy, customerPolicyLoader, getCustomerPolicyReq } = props

  const history = useHistory()
  const { policyId, productType } = useParams()

  // const [{ offlineQuoteDetailData }, offlineQuoteDetailReq] = useGetOfflineQuoteDetail()
  const [{ AGENT_PAYING_LOADER, GET_PAYMENT_URL_LOADER }] =
    useLoaderContextValue()

  const policy = useMemo(() => {
    if (customerPolicy?.id) {
      return customerPolicy
    }
    // } else if (offlineQuoteDetailData?.id) {
    //   return { ...offlineQuoteDetailData?.policy_details }
    // }
    return {}
  }, [customerPolicy])

  useEffect(() => {
    // On init, hit get policy API
    // if ([MANUAL_ORDER, FLEET_POLICY].includes(productType)) {
    //   offlineQuoteDetailReq({ quoteId: policyId })
    // } else {
    getCustomerPolicyReq(policyId)
    // }
  }, [policyId, productType, getCustomerPolicyReq])

  const handleClickClose = useCallback(() => {
    history.goBack()
  }, [history])

  const handleClickViewQS = useCallback(() => {
    const qsLink = getQsLink(policy)
    window.open(qsLink, '_blank')
  }, [policy])

  return (
    <Container
      mitraHeader
      loader={
        customerPolicyLoader || AGENT_PAYING_LOADER || GET_PAYMENT_URL_LOADER
      }
      hideBottomTabs
      hideGuardianInfo
      showCloseIcon
      onClose={() => history.replace('/dashboard')}
      onBackClick={() => history.goBack()}
    >
      <PaymentPageStyle>
        <PolicySummary>
          <div className="application-number">{policy?.application_no}</div>
          <div className="policy-detail">
            {POLICY_SUMMARY.map((item) => (
              <div>
                <div className="label">{item.label}</div>
                <div className="data">{get(policy, item.key, '-')}</div>
              </div>
            ))}
          </div>
        </PolicySummary>
        <XenditPayment
          policy={policy}
          policyId={policyId}
          stepsHeader={false}
          paymentBy="customer"
        />
        <ButtonContainer>
          <Button variant="outlined" onClick={handleClickClose}>
            {LANG_STRINGS.return}
          </Button>
        </ButtonContainer>
      </PaymentPageStyle>
    </Container>
  )
}

export default connect(
  (state) => ({
    customerPolicy: state.Customer.customerPolicyData,
    customerPolicyDataStatus: state.Customer.customerPolicyDataStatus,
    customerPolicyLoader: state.Loading.GET_CUSTOMER_POLICY,
  }),
  {
    getCustomerPolicyReq: customerActions.getCustomerPolicy,
  }
)(CustomerPaymentContainer)
